<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-scale-balanced text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Stoichiometry Calculator</h5><p class="text-muted small mb-0">Calculate mole ratios and limiting reagents</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-12"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Balanced Equation</label><input type="text" id="in-eq" class="form-control form-control-lg" value="2H2 + O2 = 2H2O" placeholder="e.g. 2H2 + O2 = 2H2O"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Known Substance</label><input type="text" id="in-known" class="form-control form-control-lg" value="H2"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Known Moles</label><input type="number" id="in-mol" class="form-control form-control-lg" value="4" step="0.01"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Target Substance</label><input type="text" id="in-target" class="form-control form-control-lg" value="H2O"></div><div class="col-12"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" id="in-step" checked><label class="form-check-label small fw-bold text-secondary" for="in-step">Show Step-by-Step</label></div></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Method:</b> Use mole ratios from balanced equation coefficients</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){function getCoeff(eq,sub){var re=new RegExp("(\\d*)"+sub.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"));var m=eq.match(re);if(!m)return 0;return parseInt(m[1])||1;}document.getElementById("btn-calc").addEventListener("click",function(){var eq=document.getElementById("in-eq").value,known=document.getElementById("in-known").value.trim(),mol=parseFloat(document.getElementById("in-mol").value)||0,target=document.getElementById("in-target").value.trim();var ck=getCoeff(eq,known),ct=getCoeff(eq,target);if(ck===0||ct===0){document.getElementById("out-main").textContent="Not found";return;}var result=mol*(ct/ck);document.getElementById("out-main").textContent=result.toFixed(4);document.getElementById("out-unit").textContent="moles of "+target;document.getElementById("out-detail").innerHTML='<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Known Coeff</div><div class="h5 fw-bold mb-0 text-primary">'+ck+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Target Coeff</div><div class="h5 fw-bold mb-0 text-info">'+ct+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Ratio</div><div class="h5 fw-bold mb-0 text-success">'+ct+':'+ck+'</div></div></div>';var ins=["Mole ratio "+target+":"+known+" = "+ct+":"+ck,mol+" mol "+known+" × ("+ct+"/"+ck+") = <b>"+result.toFixed(4)+" mol "+target+"</b>"];if(document.getElementById("in-step").checked){ins.push("Step 1: Identify coefficients from balanced equation");ins.push("Step 2: Set up mole ratio: "+ct+"/"+ck);ins.push("Step 3: Multiply known moles by ratio");}document.getElementById("out-ins").innerHTML='<ul class="list-unstyled mb-0">'+ins.map(function(i){return'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+i+'</li>';}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-eq").value="2H2 + O2 = 2H2O";document.getElementById("in-known").value="H2";document.getElementById("in-mol").value=4;document.getElementById("in-target").value="H2O";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Stoichiometry: "+document.getElementById("out-main").textContent+" mol");var b=this;b.innerHTML="<i class=\"fas fa-check me-1\"></i>Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>